/**
 * End-to-end smoke test of the Facebook Reels flow (Phase 3) and dashboard login, over MCP with
 * the real agent tokens and real MP4 files generated by ffmpeg. Deletes everything it created.
 *
 *   bun --env-file=.env --env-file=.env.local --env-file=.env.agents.local scripts/smoke-reels.ts [baseUrl]
 */
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";
import { DeleteObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { inArray, sql } from "drizzle-orm";
import { db } from "@/lib/db";
import { assets, cycles, ideaGraveyard, ideas, jobs, performance, publications, reviews, transitions } from "@/lib/db/schema";
import { operatorCookie } from "./lib/operator-cookie";
import { ASSET_BUCKET } from "@/lib/storage";
import { decidePublication, importPerformance, markReelPosted, performanceOverview, recordReelRestriction } from "@/lib/studio/service";

const base = process.argv.find((a) => a.startsWith("http")) ?? "http://localhost:3100";
const cyclesMade: string[] = [];
const step = (m: string) => console.log(`✓ ${m}`);
function expect(c: unknown, m: string): asserts c {
  if (!c) throw new Error(m);
}

async function connect(role: string) {
  const c = new Client({ name: `smoke-${role}`, version: "0" });
  await c.connect(
    new StreamableHTTPClientTransport(new URL("/api/mcp", base), {
      requestInit: { headers: { Authorization: `Bearer ${process.env[`STUDIO_TOKEN_${role.toUpperCase()}`]}` } },
    }),
  );
  return c;
}
async function call(c: Client, name: string, a: Record<string, unknown> = {}) {
  const r = await c.callTool({ name, arguments: a });
  const t = (r.content as { text: string }[])[0]?.text ?? "";
  if (r.isError) throw new Error(`${name}: ${t}`);
  return JSON.parse(t);
}
async function callError(c: Client, name: string, a: Record<string, unknown>) {
  const r = await c.callTool({ name, arguments: a });
  expect(r.isError, `${name} should fail`);
  return (r.content as { text: string }[])[0]?.text ?? "";
}

/** 35-second 1080x1920 H.264/AAC reel; `gainDb` sets how loud the tone is. */
function makeReel(dir: string, name: string, gainDb: number, pattern = "testsrc2") {
  const out = join(dir, name);
  execFileSync("ffmpeg", [
    "-hide_banner", "-loglevel", "error", "-y",
    "-f", "lavfi", "-i", `${pattern}=size=1080x1920:rate=30:duration=35`,
    "-f", "lavfi", "-i", "sine=frequency=440:duration=35",
    "-af", `volume=${gainDb}dB`, "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p", "-c:a", "aac", "-shortest", out,
  ]);
  return readFileSync(out);
}

async function rubricReview(c: Client, tool: string, jobId: string, score: number, extra: Record<string, unknown> = {}) {
  const ctx = await call(c, "get_job", { job_id: jobId });
  const gates = Object.fromEntries(ctx.rubric.gates.map((g: { id: string }) => [g.id, true]));
  const scores = Object.fromEntries(ctx.rubric.criteria.map((x: { id: string }) => [x.id, score]));
  const feedback = Object.fromEntries(ctx.rubric.criteria.map((x: { id: string }) => [x.id, "Perjelas transisi scene 2"]));
  return call(c, tool, { job_id: jobId, gates, scores, feedback, summary: "uji", ...extra });
}

async function upload(linda: Client, jobId: string, bytes: Buffer) {
  const up = await call(linda, "create_asset_upload", { job_id: jobId, content_type: "video/mp4" });
  const put = await fetch(up.uploadUrl, { method: "PUT", headers: up.headers, body: new Uint8Array(bytes) });
  expect(put.ok, `PUT ${put.status}`);
  return call(linda, "submit_asset", { job_id: jobId, s3_key: up.s3Key, content_type: "video/mp4", notes: "smoke" });
}

const scene = (d: number) => ({ duration_sec: d, visual: "Animasi teks besar di tengah layar", narration: "Tahukah kamu…" });
const storyboard = { hook: "Pertanyaan besar muncul di layar dalam 2 detik", scenes: [scene(3), scene(16), scene(16)], cta: "Ikuti untuk fakta lain" };

async function run(dir: string) {
  // Login gate
  const anon = await fetch(new URL("/dashboard/reels", base), { redirect: "manual" });
  expect(anon.status === 307 && anon.headers.get("location")?.includes("/login?next=%2Fdashboard%2Freels"), `gate: ${anon.status} ${anon.headers.get("location")}`);
  const cookie = await operatorCookie();
  const signedIn = await fetch(new URL("/login", base), { redirect: "manual", headers: { Cookie: cookie } });
  expect(signedIn.status === 307 && signedIn.headers.get("location")?.endsWith("/dashboard"), "signed-in /login should bounce to /dashboard");
  const forged = await fetch(new URL("/dashboard", base), { redirect: "manual", headers: { Cookie: `${cookie.slice(0, -2)}AA` } });
  expect(forged.status === 307, "forged cookie must be refused");
  // A session whose version is outdated (password changed elsewhere) must not open the dashboard.
  await db.execute(sql`update users set session_version = session_version + 1 where role = 'superadmin'`);
  const revoked = await fetch(new URL("/dashboard", base), { redirect: "manual", headers: { Cookie: cookie } });
  await db.execute(sql`update users set session_version = session_version - 1 where role = 'superadmin'`);
  expect(revoked.status === 307 && revoked.headers.get("location")?.includes("/login"), `revoked session must be redirected before rendering, got ${revoked.status}`);
  const loginPage = await (await fetch(new URL("/login", base))).text();
  expect(loginPage.includes("Masuk ke Studio") && /autocomplete="current-password"/i.test(loginPage), "login page");
  step("login: dashboard dialihkan ke /login (dengan next), cookie palsu dan sesi kedaluwarsa ditolak, halaman login tampil");

  const [admin, shion, lukas, linda, kechlyn] = await Promise.all(["admin", "shion", "lukas", "linda", "kechlyn"].map(connect));
  const open = async () => {
    const { cycleIds } = await call(admin, "open_cycle", { platform: "facebook_reels" });
    cyclesMade.push(...cycleIds);
    const ctx = await call(shion, "get_next_job", { role: "shion" });
    expect(ctx.job.line === "reel" && ctx.reelsChannel, "reel context");
    await call(shion, "submit_idea", { job_id: ctx.job.id, content: { title: "Fakta gurita punya tiga jantung", angle: "kejutan biologi" } });
    await call(lukas, "get_next_job", { role: "lukas" });
    const r = await rubricReview(lukas, "submit_idea_review", ctx.job.id, 9);
    expect(r.nextStatus === "storyboard_pending", r.nextStatus);
    return ctx.job.id as string;
  };

  const jobId = await open();
  await call(shion, "get_next_job", { role: "shion" });
  const bad = await callError(shion, "submit_storyboard", { job_id: jobId, content: { hook: "Hook singkat sekali", scenes: [scene(8), scene(4)] } });
  expect(bad.includes("total durasi 12") && bad.includes("scene pertama"), bad);
  await call(shion, "submit_storyboard", { job_id: jobId, content: storyboard });
  await call(lukas, "get_next_job", { role: "lukas" });
  const sb = await rubricReview(lukas, "submit_idea_review", jobId, 9);
  expect(sb.nextStatus === "executing", sb.nextStatus);
  step("reel: ide → storyboard (12 detik ditolak server, 35 detik lolos Lukas) → eksekusi");

  await call(linda, "get_next_job", { role: "linda" });
  const quiet = await upload(linda, jobId, makeReel(dir, "quiet.mp4", -6));
  expect(quiet.nextStatus === "exec_revision" && quiet.autoCheck.problems.some((p: string) => p.includes("terlalu pelan")), JSON.stringify(quiet.autoCheck));
  step(`ffmpeg membaca file asli: ${quiet.autoCheck.problems.find((p: string) => p.includes("pelan"))}`);

  const goodBytes = makeReel(dir, "good.mp4", 8);
  const good = await upload(linda, jobId, goodBytes);
  expect(good.nextStatus === "final_review", `good reel: ${JSON.stringify(good.autoCheck)}`);
  const k = await call(kechlyn, "get_next_job", { role: "kechlyn" });
  const v = k.latestAsset.video;
  expect(k.rubric.id === "asset-reel" && k.latestAsset.framesUrl && v.width === 1080 && v.videoCodec === "h264", "Kechlyn context");
  const frames = await fetch(k.latestAsset.framesUrl);
  expect(frames.ok && frames.headers.get("content-type")?.includes("image"), "keyframe sheet download");
  step(`reel lolos cek teknis (${v.width}×${v.height}, ${v.durationSec}s, ${v.loudnessLufs} LUFS); Kechlyn dapat video + lembar 3 keyframe`);

  await rubricReview(kechlyn, "submit_asset_review", jobId, 8);
  await call(kechlyn, "get_next_job", { role: "kechlyn" });
  const noCaption = await callError(kechlyn, "submit_publication_prep", { job_id: jobId, title: "Gurita tiga jantung", hashtags: [], ai_label: true });
  expect(noCaption.includes("Caption wajib"), noCaption);
  const pub = await call(kechlyn, "submit_publication_prep", {
    job_id: jobId, title: "Gurita tiga jantung", caption: "Kamu cuma punya satu jantung. Gurita punya tiga.", hashtags: ["fakta", "#Fakta", "sains"], ai_label: true,
  });
  expect(pub.fileName.endsWith(".mp4") && pub.hashtags.join(" ") === "#fakta #sains", JSON.stringify(pub));
  await decidePublication(pub.publicationId, true, 8, "Oke");
  const reelsPage = await (await fetch(new URL("/dashboard/reels", base), { headers: { Cookie: cookie } })).text();
  expect(reelsPage.includes("Gurita tiga jantung") && reelsPage.includes("Tandai Terposting"), "reels kit on page");
  step("metadata reels (caption wajib, hashtag dinormalisasi) → approval → muncul di kit posting");

  await markReelPosted(pub.publicationId, "https://example.com/x").then(
    () => {
      throw new Error("non-facebook link should fail");
    },
    () => undefined,
  );
  await markReelPosted(pub.publicationId, "https://www.facebook.com/reel/123456789/?s=share");
  const day = new Date().toISOString().slice(0, 10);
  const imp = await importPerformance("facebook_reels", [
    { fileName: null, postUrl: "https://m.facebook.com/reel/123456789", day, downloads: 0, views: 1520, revenueUsd: 0.42 },
  ]);
  const perf = await performanceOverview("facebook_reels", 7);
  expect(imp.imported === 1 && perf.totals.views === 1520, `views import ${JSON.stringify(imp)} ${JSON.stringify(perf.totals)}`);
  step("tandai terposting (link Facebook saja) → impor tayangan dicocokkan lewat link meski beda subdomain/query");

  const job2 = await open();
  await call(shion, "get_next_job", { role: "shion" });
  await call(shion, "submit_storyboard", { job_id: job2, content: storyboard });
  await call(lukas, "get_next_job", { role: "lukas" });
  await rubricReview(lukas, "submit_idea_review", job2, 9);
  await call(linda, "get_next_job", { role: "linda" });
  const dup = await upload(linda, job2, goodBytes);
  expect(dup.autoCheck.problems.some((p: string) => p.includes("tidak orisinal")), JSON.stringify(dup.autoCheck));
  step("reel duplikat di job lain ditolak (keyframe dHash)");

  await recordReelRestriction(pub.publicationId, "Konten tidak orisinal");
  const ctx2 = await call(shion, "get_job", { job_id: job2 });
  expect(ctx2.platformRejections.some((r: { reason: string }) => r.reason.includes("tidak orisinal")), "restriction in context");
  step("dibatasi Meta → job diarsipkan, alasan masuk konteks agen");

  await Promise.all([admin, shion, lukas, linda, kechlyn].map((c) => c.close()));
  console.log("\nREELS SMOKE TEST PASSED");
}

async function cleanup() {
  const keys: string[] = [];
  if (cyclesMade.length) {
    const ids = (await db.select({ id: jobs.id }).from(jobs).where(inArray(jobs.cycleId, cyclesMade))).map((j) => j.id);
    if (ids.length) {
      const rows = await db.select({ k: assets.s3Key, m: assets.media }).from(assets).where(inArray(assets.jobId, ids));
      for (const r of rows) keys.push(r.k, ...(r.m?.framesKey ? [r.m.framesKey] : []));
      const pubIds = (await db.select({ id: publications.id }).from(publications).where(inArray(publications.jobId, ids))).map((p) => p.id);
      if (pubIds.length) {
        await db.delete(performance).where(inArray(performance.publicationId, pubIds));
        await db.delete(publications).where(inArray(publications.id, pubIds));
      }
      await db.delete(ideaGraveyard).where(inArray(ideaGraveyard.jobId, ids));
      for (const t of [transitions, reviews, ideas, assets] as const) await db.delete(t).where(inArray(t.jobId, ids));
      await db.delete(jobs).where(inArray(jobs.id, ids));
    }
    await db.delete(cycles).where(inArray(cycles.id, cyclesMade));
  }
  const s3 = new S3Client({ region: process.env.AWS_REGION ?? "auto", endpoint: process.env.AWS_ENDPOINT_URL_S3, forcePathStyle: true });
  for (const Key of keys) await s3.send(new DeleteObjectCommand({ Bucket: ASSET_BUCKET, Key })).catch(() => {});
  console.log("(data uji dibersihkan)");
}

const dir = mkdtempSync(join(tmpdir(), "smoke-reels-"));
try {
  await run(dir);
} catch (e) {
  console.error("\nREELS SMOKE TEST FAILED:", e instanceof Error ? e.message : e);
  process.exitCode = 1;
} finally {
  rmSync(dir, { recursive: true, force: true });
  await cleanup();
  process.exit(process.exitCode ?? 0);
}
